namespace sv_d4b896fb99054c8a8b1274144549818b.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public record StatusUpdate(string Description, DateTimeOffset Timestamp);

using sv_d4b896fb99054c8a8b1274144549818b.Client.Services;

namespace sv_d4b896fb99054c8a8b1274144549818b.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 18, 14, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 7, 12, 9, 0, 0, TimeSpan.Zero)),
                new("Arrived at sorting facility", new DateTimeOffset(2026, 7, 13, 3, 30, 0, TimeSpan.Zero)),
                new("In transit to destination", new DateTimeOffset(2026, 7, 14, 11, 15, 0, TimeSpan.Zero))
            }),
        ["TRK-002"] = new ShipmentDetails(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            new DateTimeOffset(2026, 7, 14, 10, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 7, 10, 8, 0, 0, TimeSpan.Zero)),
                new("Arrived at regional hub", new DateTimeOffset(2026, 7, 11, 16, 45, 0, TimeSpan.Zero)),
                new("Out for delivery", new DateTimeOffset(2026, 7, 14, 7, 0, 0, TimeSpan.Zero)),
                new("Delivered", new DateTimeOffset(2026, 7, 14, 9, 32, 0, TimeSpan.Zero))
            }),
        ["TRK-003"] = new ShipmentDetails(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            new DateTimeOffset(2026, 7, 22, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Label created", new DateTimeOffset(2026, 7, 15, 0, 0, 0, TimeSpan.Zero))
            })
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

using sv_d4b896fb99054c8a8b1274144549818b.Client.Services;

namespace sv_d4b896fb99054c8a8b1274144549818b;

public static class ShipmentApi
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        app.MapGet("/api/shipments/{trackingNumber}", async (
            string trackingNumber,
            IShipmentService service,
            CancellationToken ct) =>
        {
            try
            {
                var shipment = await service.GetShipmentAsync(trackingNumber, ct);
                return Results.Ok(shipment);
            }
            catch (KeyNotFoundException)
            {
                return Results.NotFound();
            }
        });
    }
}

using System.Net;
using System.Net.Http.Json;

namespace sv_d4b896fb99054c8a8b1274144549818b.Client.Services;

public class HttpShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public HttpShipmentService(HttpClient http)
    {
        _http = http;
    }

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
        }

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct)
            ?? throw new InvalidOperationException("Received null response from shipment API.");
    }
}

