@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_d4b896fb99054c8a8b1274144549818b.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<Shipment> Logger
@implements IAsyncDisposable

<h2>Shipment Tracking</h2>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment details for @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-message">
        <p>@_errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="shipment-details">
        <dl>
            <dt>Tracking Number</dt>
            <dd>@_shipment.TrackingNumber</dd>

            <dt>Status</dt>
            <dd>@_shipment.Status</dd>

            <dt>Location</dt>
            <dd>@_shipment.Location</dd>

            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        @if (_shipment.Updates.Count == 0)
        {
            <p>No status updates available.</p>
        }
        else
        {
            <ul>
                @foreach (var update in _shipment.Updates)
                {
                    <li>
                        <strong>@update.Timestamp.ToString("g")</strong> &mdash; @update.Description
                    </li>
                }
            </ul>
        }
    </div>
}

@code {
    private CancellationTokenSource? _cts;
    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;

    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    protected override Task OnParametersSetAsync()
    {
        return LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }

        _cts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested && _cts.Token != ct)
        {
            // Superseded by a newer navigation — silently discard.
            return;
        }
        catch (OperationCanceledException)
        {
            Logger.LogWarning("Shipment request for {TrackingNumber} timed out.", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (KeyNotFoundException)
        {
            _errorMessage = $"No shipment found for tracking number \"{TrackingNumber}\".";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}.", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }
}

